// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./ComplianceToken.sol";
import {TransparentUpgradeableProxy} from "@openzeppelin/contracts/proxy/transparent/TransparentUpgradeableProxy.sol";
import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";

/**
 * @title ComplianceTokenFactory
 * @dev Factory contract for creating new ComplianceToken proxy instances
 */
contract ComplianceTokenFactory is OwnableUpgradeable {
    // complianceTokenImpl contract address
    address public complianceTokenImpl;

    // Mapping to track created tokens
    mapping(address => bool) public isCreatedToken;

    // Array to store all created token addresses
    address[] public createdTokens;

    // Events
    event TokenCreated(address indexed token, string name, string symbol);

    function initialize(address owner) public initializer {
        __Ownable_init(owner);
        complianceTokenImpl = address(new ComplianceToken());
    }

    /**
     * @dev Creates a new ComplianceToken proxy instance
     * @param name Token name
     * @param symbol Token symbol
     * @return proxy Address of the newly created proxy contract
     */
    function createComplianceToken(
        string memory name,
        string memory symbol,
        address admin,
        address chairman,
        address whitelister,
        address minterA,
        address minterB,
        address depositAddr,
        address withdrawAddr,
        address houseAddr,
        address deadAddr
    ) external onlyOwner returns (address proxy) {
        // Encode initialization data
        bytes memory initData = abi.encodeWithSelector(
            ComplianceToken.initialize.selector,
            name,
            symbol,
            chairman,
            whitelister,
            minterA,
            minterB,
            depositAddr,
            withdrawAddr,
            houseAddr,
            deadAddr
        );

        // Deploy proxy contract
        proxy = address(new TransparentUpgradeableProxy(complianceTokenImpl, admin, initData));

        // Mark as created token and add to array
        isCreatedToken[proxy] = true;
        createdTokens.push(proxy);

        emit TokenCreated(proxy, name, symbol);

        return proxy;
    }

    function setComplianceTokenImpl(address newComplianceTokenImpl) external onlyOwner {
        complianceTokenImpl = newComplianceTokenImpl;
    }

    /**
     * @dev Returns the total number of created tokens
     * @return The number of created tokens
     */
    function getCreatedTokensCount() external view returns (uint256) {
        return createdTokens.length;
    }

    /**
     * @dev Returns all created token addresses
     * @return Array of all created token addresses
     */
    function getAllCreatedTokens() external view returns (address[] memory) {
        return createdTokens;
    }
}

