                    return 22;
                }
            } else if (from == depositAddr) {
                // asset transfer transaction
                if (to != withdrawAddr) {
                    return 23;
                }
            }
        }
        return 0;
    }

    /**
     * @dev Provides human-readable error messages for transfer restrictions.
     * @param restrictionCode The restriction code.
     */
    function messageForTransferRestriction(uint8 restrictionCode) public pure returns (string memory) {
        if (restrictionCode == 10) {
            return "only withdraw address and deposit address can transfer tokens to dead address";
        } else if (restrictionCode == 11) {
            return "only deposit address can transfer tokens to house address";
        } else if (restrictionCode == 20) {
            return "the destination address is not the corresponding deposit address";
        } else if (restrictionCode == 21) {
            return "the destination address is not the collection transaction";
        } else if (restrictionCode == 22) {
            return "the destination address is not the user whitelist address";
        } else if (restrictionCode == 23) {
            return "the destination address is not the withdraw address";
        }
        return "this restrictionCode does not exist";
    }
}

